Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('71be9d37429b8859bedd44ecd80166429cba2208ddaba3c277e98d7064a5acf9',), event=Authored(todo='tileslibrary', at=datetime(2026, 11, 24, 13, 19, 42, 838794), actor='bmabsout', kind='todo', created=datetime(2026, 11, 24, 0, 0, 0), body="The tiled layout is a library a stranger's application can use: the module in a crate of its own with a guide, a runnable example and its laws; the bound of tiles a workspace and the open rule are parameters with today's as the defaults; a page's address is an optional part of the page's trait; a divider's shares are as fine as a host wants and a leaf moves to any place; a layout can be kept without the address grammar; and a small adapter places a host's elements from the arrangement and keeps hidden ones, depending on nothing of this application.", spec=Flat(value=0.6), rationale=('The module names nothing of this application and no existing', 'implementation does its work, so its reuse is worth making real; the', 'host half is tied to this application today.'), category='', waiting_on='', detail="State on 2026-11-24: a survey of existing implementations found none to reuse. Layout engines for flex and grid (taffy and others) and constraint solvers compute in floats and have no rule for showing the focused child and as many neighbours as fit; the nearest tree models are bound to a user-interface toolkit or lay out with floats and have no narrow-screen collapse, address or laws; the web docking libraries own their panels' elements and their own mutable layout. What is specific to this application in the module's face: a fixed bound of four, three share steps, a fixed open rule, an address and a home required of every page, and two measures of a phone's browser. The design note's prior art names no Rust crate: add the two nearest with the reasons.", source=None, subtodos=(), notes=(), note=''))